A=[[2,2,2,2],[2,0,0,0],[2,0,2,0],[2,2,2,0]]
B=[[2,2,2,2],[2,0,0,0],[2,0,0,2],[2,0,2,2]]
# tile row/col positions in 4x4 board
placements={(0,0):A,(0,1):B,(0,2):B,(0,3):B,(1,0):A,(2,0):B,(2,3):B,(3,0):A,(3,2):B,(3,3):B}
out=[[0]*19 for _ in range(19)]
for (tr,tc),pat in placements.items():
    for i in range(4):
        for j in range(4):
            v=pat[i][j]
            if v==2 and (i,j)==(tr,tc): v=8
            out[5*tr+i][5*tc+j]=v
print('\n'.join(' '.join(map(str,row)) for row in out))

